/// What the route of contract `create-tenant` needs from the deployment beyond its handler.
pub trait CreateTenantHooks: Send + Sync + 'static + QuotaCounter + AuditClock {
    /// The payload of error `quota-exceeded` of contract `create-tenant` when quota `quota-create-tenant` refuses a call, `retry_after` before the window ends.
    fn quota_create_tenant_exceeded(&self, retry_after: std::time::Duration) -> types::Quota;

    /// Appends an entry of audit `tenant-created` (record `rec-tenant-audit`) after a successful call of contract `create-tenant`. An `Err` answers `internal`.
    fn append_tenant_created(
        &self,
        entry: crate::audits::TenantCreatedEntry,
    ) -> impl std::future::Future<Output = Result<(), String>> + Send;
}

/// Answers one call of contract `create-tenant`.
async fn answer_create_tenant<S: CreateTenantHandler, H: CreateTenantHooks>(
    handler: &S,
    hooks: &H,
    caller: strata_runtime::Caller,
    request: crate::contracts::CreateTenantRequest,
) -> Result<
    crate::contracts::CreateTenantResponse,
    strata_runtime::Failure<crate::contracts::CreateTenantError>,
> {
    if let Err(broken) = request.validate() {
        return Err(refusal(
            strata_runtime::FailureCode::InvalidRequest,
            broken.to_string(),
        ));
    }
    let principal = principal(&caller);
    if !crate::policies::authorize_create_tenant(&principal, &request).is_allowed() {
        return Err(refusal(
            strata_runtime::FailureCode::Forbidden,
            "the policies of contract create-tenant refuse this caller",
        ));
    }
    match hooks
        .count(&crate::quotas::QUOTA_CREATE_TENANT, &principal)
        .await
        .map_err(|why| refusal(strata_runtime::FailureCode::Unavailable, why))?
    {
        crate::quotas::QuotaOutcome::Allowed(_) => {}
        crate::quotas::QuotaOutcome::Exceeded { retry_after, .. } => {
            return Err(strata_runtime::Failure::Contract {
                error: crate::contracts::CreateTenantError::QuotaExceeded(
                    hooks.quota_create_tenant_exceeded(retry_after),
                ),
            });
        }
    }
    let audited = request.clone();
    let response = handler
        .handle(request)
        .await
        .map_err(|error| strata_runtime::Failure::Contract { error })?;
    let entry = crate::audits::audit_tenant_created(&principal, &audited, &response, hooks.now())
        .map_err(|why| refusal(strata_runtime::FailureCode::Internal, why.to_string()))?;
    hooks
        .append_tenant_created(entry)
        .await
        .map_err(|why| refusal(strata_runtime::FailureCode::Internal, why))?;
    Ok(response)
}

/// Adds the route of contract `create-tenant` to `routes`, answered by `handler` after the checks the specification states for it.
pub fn serve_create_tenant<A, S, H>(
    routes: strata_runtime::Routes<A>,
    handler: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: CreateTenantHandler,
    H: CreateTenantHooks,
{
    routes.serve_checked::<CreateTenant, _, _>(
        move |caller: strata_runtime::Caller, request: crate::contracts::CreateTenantRequest| {
            let (handler, hooks) = (handler.clone(), hooks.clone());
            async move { answer_create_tenant(&*handler, &*hooks, caller, request).await }
        },
    )
}

