/// Answers one call of contract `get-account`.
async fn answer_get_account<S: GetAccountHandler, H: GetAccountHooks>(
    handler: &S,
    hooks: &H,
    caller: strata_runtime::Caller,
    request: crate::contracts::GetAccountRequest,
) -> Result<
    crate::contracts::GetAccountResponse,
    strata_runtime::Failure<crate::contracts::GetAccountError>,
> {
    let principal = principal(&caller);
    if !{
        let record = hooks
            .get_account_resource(&request)
            .await
            .map_err(|why| refusal(strata_runtime::FailureCode::Unavailable, why))?;
        crate::policies::authorize_get_account(&principal, &request, record.as_ref())
    }
    .is_allowed()
    {
        return Err(refusal(
            strata_runtime::FailureCode::Forbidden,
            "the policies of contract get-account refuse this caller",
        ));
    }
    let audited = request.clone();
    let response = handler
        .handle(request)
        .await
        .map_err(|error| strata_runtime::Failure::Contract { error })?;
    let entry = crate::audits::audit_account_read(&principal, &audited, &response, hooks.now())
        .map_err(|why| refusal(strata_runtime::FailureCode::Internal, why.to_string()))?;
    hooks
        .append_account_read(entry)
        .await
        .map_err(|why| refusal(strata_runtime::FailureCode::Internal, why))?;
    Ok(response)
}

